import { build } from 'esbuild';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const indexPath = path.join(root, 'index.html');
const outputPath = path.join(root, 'bundle.html');

let html = await readFile(indexPath, 'utf8');
const stylesheetPattern = /\s*<link rel="stylesheet" href="([^"]+)">/g;
const stylesheets = [...html.matchAll(stylesheetPattern)].map(match => match[1]);
if (stylesheets.length === 0) throw new Error('No source stylesheets were found in index.html.');
const css = (await Promise.all(stylesheets.map(file => readFile(path.join(root, file), 'utf8')))).join('\n\n');

let insertedStyles = false;
html = html.replace(stylesheetPattern, () => {
  if (insertedStyles) return '';
  insertedStyles = true;
  return `\n  <style>\n${escapeClosingTag(css, 'style')}\n  </style>`;
});

const markedSource = await readFile(path.join(root, 'lib/marked.min.js'), 'utf8');
html = replaceRequired(
  html,
  /\s*<script src="lib\/marked\.min\.js"><\/script>/,
  `\n  <script>\n${escapeClosingTag(markedSource, 'script')}\n  </script>`,
  'marked.js script'
);

const result = await build({
  entryPoints: [path.join(root, 'js/main.js')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2022'],
  treeShaking: true,
  minify: false,
  legalComments: 'none',
  write: false
});
const appSource = result.outputFiles[0].text;

html = replaceRequired(
  html,
  /\s*<script type="module" src="js\/main\.js"><\/script>/,
  `\n<script>\n${escapeClosingTag(appSource, 'script')}\n</script>`,
  'application entry script'
);

html = html.replace(
  "script-src 'self'",
  "script-src 'unsafe-inline'"
);

html = html.replace(
  '<!DOCTYPE html>',
  '<!DOCTYPE html>\n<!-- Generated by npm run build. Do not edit bundle.html directly. -->'
);

await writeFile(outputPath, html, 'utf8');
console.log(`Generated ${path.relative(root, outputPath)} from index.html and js/main.js`);

function escapeClosingTag(value, tagName) {
  return value.replace(new RegExp(`</${tagName}`, 'gi'), `<\\/${tagName}`);
}

function replaceRequired(value, pattern, replacement, label) {
  if (!pattern.test(value)) throw new Error(`Could not find the ${label} in index.html.`);
  return value.replace(pattern, replacement);
}
